<?php
declare(strict_types=1);namespace App\Http\Controllers\TeachingAssignments;use App\Http\Controllers\Controller;use App\Models\TeachingAssignmentSet;use App\Services\TeachingAssignments\TeachingAssignmentExportService;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\BinaryFileResponse;
class TeachingAssignmentExportController extends Controller {public function __invoke(Request $request,TeachingAssignmentExportService $service):BinaryFileResponse{abort_unless($request->user()->can('teaching-assignments.export'),403);$set=TeachingAssignmentSet::with('academicYear')->find($request->integer('set'))??TeachingAssignmentSet::with('academicYear')->where('status','active')->latest('activated_at')->firstOrFail();return $service->download($request->user(),$set);}}
